const app = express();

// 1) Gắn mã yêu cầu để lần vết log
let n = 0;
app.use((req, res, next) => { req.id = "req-" + ++n; next(); });

// 2) Giới hạn tần suất: tối đa 2 yêu cầu mỗi khoá
const hits = new Map();
function rateLimit(max) {
  return (req, res, next) => {
    const key = req.headers["x-client"] || "anon";
    const c = (hits.get(key) || 0) + 1;
    hits.set(key, c);
    if (c > max) return res.status(429).json({ error: "quá nhiều yêu cầu" });
    next();
  };
}
app.use(rateLimit(2));

app.get("/", (req, res) => res.json({ id: req.id }));

