const express = require("express");
const app = express();
function requireRole(role) {
  return (req, res, next) => {
    if (req.headers["x-role"] !== role) return res.status(403).json({ error: "forbidden" });
    next();
  };
}
app.get("/admin", requireRole("admin"), (req, res) => res.json({ ok: true }));
(async () => {
  const a = await app.inject({ url: "/admin", headers: { "x-role": "user" } });
  const b = await app.inject({ url: "/admin", headers: { "x-role": "admin" } });
  console.log(a.statusCode + "," + b.statusCode);
})();

