function makeBucket(capacity, refillPerSec) {
  let tokens = capacity, last = 0;
  return (now) => {
    tokens = Math.min(capacity, tokens + (now - last) * refillPerSec);
    last = now;
    if (tokens >= 1) { tokens -= 1; return true; }
    return false;
  };
}
const take = makeBucket(2, 1);
console.log([take(0), take(0), take(0), take(1), take(1.5)].join(","));
